local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local UIEventProxy = CS.Engine.UI.UIEventProxy
------------ import ------------

------------ define ------------
local switchMaskPosX = {
    on = 25,
    off = 115
}
local switchBgPath = {
    off = "UIAtlas/Setting/set_btn_switch_default.png",
    on = "UIAtlas/Setting/set_btn_switch_pressed.png"
}
------------ define ------------


---@class SettingSwitchNode
---@field Img                           	UnityEngine.RectTransform
---@field ClickArea                     	UnityEngine.RectTransform
---@field SelectedBg                    	UnityEngine.RectTransform
local SettingSwitchNode = Class("SettingSwitchNode")
function SettingSwitchNode:__init()
    self.openState = false
end

function SettingSwitchNode:__delete()
    self.openState = true
    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function SettingSwitchNode:SetCallBack(cb)
    self.__callback = cb
end

function SettingSwitchNode:Awake()
    UIEventProxy.Create(self.ClickArea.gameObject).onPointerClick = function()
        if type(self.__callback) == 'function' then
            self.__callback()
        end
    end
end

function SettingSwitchNode:FreshSwitchStatus(isOff)
    self.openState = not isOff
    local posX = isOff and switchMaskPosX.off or switchMaskPosX.on
    local path = isOff and switchBgPath.off or switchBgPath.on
    self.Img.anchoredPosition = Vector2.New(posX, self.Img.anchoredPosition.y)
    CfUtils.FillImage(self.SelectedBg,path)
end

function SettingSwitchNode:Switch()
    self:FreshSwitchStatus(self.openState)
end

function SettingSwitchNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return SettingSwitchNode